head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[multiselect > E > onrowclick]<br/>MultiSelect 컴포넌트의 아이템을 클릭했을 때 발생합니다.",
    "validation" : [
        "MultiSelect 컴포넌트의 아이템을 클릭했을 때 onrowclick 이벤트가 발생합니다.",
        "info(Object) 파라미터로 변경된 아이템에 대한 정보 객체가 전달됩니다.",
        "info.oldValue(Number) 으로 변경전에 선택되어 있던 아이템의 Value 값이 전달됩니다.",
        "info.newValue(String) 으로 변경후에 선택된 아이템의 Value 값이 전달됩니다.",
        "info.oldSelectedIndex(String) 로 변경전에 선택되어 있던 아이템의 인덱스값이 전달됩니다.",
        "info.newSelectedIndex(String) 로 변경후에 선택된 아이템의 인덱스값이 전달됩니다.",
        "변경전에 선택된 아이템이 없거나 아이템을 2 개 이상 선택하지 않은 경우 info.oldValue / info.oldSelectedIndex 는 ''(Empty String) 값을 갖습니다.",
        "onrowclick 이벤트는 선택값의 변경 여부와 관계없이 아이템을 클릭할 때마다 항상 발생합니다.",
        "이미 선택되어 있는 아이템을 다시 클릭하여 선택값이 변경되지 않는 경우에도 onrowclick 이벤트는 발생합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    scwin.comp_init();
};



// onrowclick 이벤트 핸들러 — info 파라미터(Object) 출력
scwin.target1_onrowclick = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("===== target1 onrowclick =====");
    wf_body_bottom.getObj("scwin").setReturnValue("typeof info: " + typeof info);
    wf_body_bottom.getObj("scwin").setReturnValue("info.oldValue: [" + (info ? info.oldValue : "") + "]");
    wf_body_bottom.getObj("scwin").setReturnValue("info.newValue: [" + (info ? info.newValue : "") + "]");
    wf_body_bottom.getObj("scwin").setReturnValue("info.oldSelectedIndex: [" + (info ? info.oldSelectedIndex : "") + "]");
    wf_body_bottom.getObj("scwin").setReturnValue("info.newSelectedIndex: [" + (info ? info.newSelectedIndex : "") + "]");    
};



// comp 생성
scwin.comp_init = async function () {
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let eList = $c.gcm.createEList(["onrowclick"]);

    await $c.gcm.createBasicMultiSelect('', eList);
}
